<section class="page-heading"><div><span class="eyebrow">ACCESS MANAGEMENT</span><h1>User accounts</h1><p class="muted">Manage administrator and pharmacist access to the workspace.</p></div><a class="button button-primary" href="<?= e(url('user-form')) ?>">＋ Add user</a></section>
<section class="panel">
    <p class="result-count"><?= count($users) ?> account<?= count($users) === 1 ? '' : 's' ?> in your workspace</p>
    <div class="table-wrap"><table><thead><tr><th>Username</th><th>Email</th><th>Role</th><th>Created</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td class="table-strong"><?= e($user['username']) ?><?= (int) $user['user_id'] === \App\Core\Auth::id() ? ' (you)' : '' ?></td><td><?= e($user['email']) ?></td><td><span class="badge <?= $user['role'] === 'admin' ? 'badge-accent' : 'badge-neutral' ?>"><?= e(ucfirst($user['role'])) ?></span></td><td><?= e(date('M j, Y', strtotime($user['created_at']))) ?></td><td><div class="row-actions"><a class="button button-quiet button-small" href="<?= e(url('user-form', ['id' => $user['user_id']])) ?>">Edit</a><?php if ((int) $user['user_id'] !== \App\Core\Auth::id()): ?><form method="post" action="<?= e(url('user-delete')) ?>" data-confirm="Delete this user account?"><?= \App\Core\Csrf::field() ?><input type="hidden" name="id" value="<?= e($user['user_id']) ?>"><button class="button button-quiet button-small button-danger-text" type="submit">Delete</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div>
</section>
